      if ((op2 & 0b1100111) === 0b0000001) return this._e32_ldst_single(A, A4, hw1, hw2, i);
      if ((op2 & 0b1100111) === 0b0000011) return this._e32_ldst_single(A, A4, hw1, hw2, i);
      if ((op2 & 0b1100111) === 0b0000101) return this._e32_ldst_single(A, A4, hw1, hw2, i);
      if ((op2 & 0b1110000) === 0b0100000) return this._e32_dp_register(A, A4, hw1, hw2, i);
