    if ((op2 & 0b1100100) === 0b0000000) return this._emitLdmStm32(A, hw1, hw2, i);   // LDM/STM.W
    if ((op2 & 0b1100000) === 0b0100000) return this._e32_dp_shifted_reg(A, A4, hw1, hw2, i);
