      const imm8 = hw2 & 0xff, P = (hw2 >>> 10) & 1, U = (hw2 >>> 9) & 1, W = (hw2 >>> 8) & 1;
      if (rt === 15 || (rn === 15)) return this._fbEmit(hw1, hw2, A, 4, i);   // exotic PC forms -> fallback
